#!/usr/bin/env node
/**
 * Fails when `prisma/schema.prisma` no longer matches `ResearchOS.sql`.
 *
 * Why this is not `prisma migrate diff`:
 *
 * The schema contains 47 CHECK constraints, 91 DEFERRABLE foreign keys,
 * expression indexes, comments, views and triggers. The Prisma schema
 * language cannot represent any of them, so the datamodel is structurally
 * incomplete. A migration generated by Prisma would not reproduce the
 * database: measured against the SQL, it loses every CHECK constraint,
 * view, trigger, DEFERRABLE foreign key, expression index and column
 * comment.
 *
 * `prisma migrate diff` is also not a usable signal here. Prisma 7's
 * differ is blind to these objects: dropping a CHECK constraint, a view
 * or a trigger from the database and diffing again still reports an
 * "empty migration". A check that cannot fail carries no information.
 *
 * This script compares introspection against introspection:
 *
 *   1. Build a scratch database from `ResearchOS.sql`.
 *   2. Introspect it and run the same transformation the generator uses.
 *   3. Compare the result with the committed `prisma/schema.prisma`.
 *
 * Both sides come from the same introspection engine, so the objects that
 * Prisma cannot represent are invisible to both and produce no noise. What is
 * left is exactly the signal we want: the datamodel no longer describes the
 * SQL.
 *
 * Usage:
 *   pnpm --filter @researchos/database db:drift
 */
import { existsSync, readFileSync, rmSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { introspect } from './introspect-schema.mjs';
import {
  applySql,
  createDatabase,
  databaseName,
  dropDatabase,
  loadEnvironment,
  prisma,
  schemaFile,
  waitForPort,
} from './lib.mjs';

loadEnvironment();

/** The name of the scratch database that the check builds. */
const scratchDatabase = 'researchos_drift_check';

/**
 * Returns the lines that differ between two texts.
 *
 * A simple longest common subsequence based diff is enough here, because the
 * two files are structurally identical when there is no drift.
 */
function diffLines(left, right) {
  const a = left.split('\n');
  const b = right.split('\n');

  // The longest common subsequence table.
  const lengths = Array.from({ length: a.length + 1 }, () =>
    new Uint32Array(b.length + 1),
  );

  for (let i = a.length - 1; i >= 0; i -= 1) {
    for (let j = b.length - 1; j >= 0; j -= 1) {
      lengths[i][j] =
        a[i] === b[j]
          ? lengths[i + 1][j + 1] + 1
          : Math.max(lengths[i + 1][j], lengths[i][j + 1]);
    }
  }

  const changes = [];
  let i = 0;
  let j = 0;

  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      i += 1;
      j += 1;
      continue;
    }

    if (lengths[i + 1][j] >= lengths[i][j + 1]) {
      changes.push({ kind: 'removed', line: a[i], number: i + 1 });
      i += 1;
    } else {
      changes.push({ kind: 'added', line: b[j], number: j + 1 });
      j += 1;
    }
  }

  while (i < a.length) {
    changes.push({ kind: 'removed', line: a[i], number: i + 1 });
    i += 1;
  }

  while (j < b.length) {
    changes.push({ kind: 'added', line: b[j], number: j + 1 });
    j += 1;
  }

  return changes;
}

/**
 * Entry point.
 */
async function main() {
  if (!existsSync(schemaFile)) {
    console.error(
      `${schemaFile} does not exist. Run "pnpm --filter @researchos/database db:schema" first.`,
    );
    process.exit(1);
  }

  const committed = readFileSync(schemaFile, 'utf8');
  const url = new URL(process.env.DATABASE_URL);
  const port = Number(url.port || 5432);

  console.log('Waiting for PostgreSQL ...');
  await waitForPort(port);

  console.log(`Building the scratch database "${scratchDatabase}" ...`);
  dropDatabase(scratchDatabase);
  createDatabase(scratchDatabase);

  try {
    applySql(scratchDatabase);

    console.log('Introspecting the scratch database ...');
    const generated = introspect(scratchDatabase);

    // The committed file went through `prisma format`, so the generated one
    // has to be formatted as well before the two can be compared.
    const temporarySchema = resolve(
      schemaFile.replace(/\.prisma$/, ''),
      '..',
      '.drift-check.prisma',
    );

    const { writeFileSync } = await import('node:fs');
    writeFileSync(temporarySchema, generated, 'utf8');

    try {
      prisma(['format', '--schema', temporarySchema]);
      const formatted = readFileSync(temporarySchema, 'utf8');

      if (formatted === committed) {
        console.log('No drift. The datamodel matches ResearchOS.sql.');
        return;
      }

      const changes = diffLines(committed, formatted);

      console.error('');
      console.error('Drift detected. prisma/schema.prisma does not match ResearchOS.sql.');
      console.error('');

      for (const change of changes.slice(0, 60)) {
        const marker = change.kind === 'removed' ? '-' : '+';
        console.error(`  ${marker} ${change.line}`);
      }

      if (changes.length > 60) {
        console.error(`  ... and ${changes.length - 60} more lines`);
      }

      console.error('');
      console.error(
        'Regenerate the datamodel with "pnpm --filter @researchos/database db:schema".',
      );

      process.exitCode = 1;
    } finally {
      rmSync(temporarySchema, { force: true });
    }
  } finally {
    console.log('Dropping the scratch database ...');
    dropDatabase(scratchDatabase);
  }
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  await main();
}
